{
  "mushroom": "Amanita muscaria (fly agaric), fruiting bodies",
  "composition": [
    {
      "compound": "Ibotenic acid",
      "amount": "~300–1000 mg/kg dry weight (0.03–0.1% of dry weight)",
      "effect": "Glutamate (NMDA) receptor agonist causing confusion, agitation, nausea and neuroexcitatory delirium; decarboxylates to muscimol on drying or heating."
    },
    {
      "compound": "Muscimol",
      "amount": "~200–500 mg/kg dry weight (0.02–0.05% of dry weight)",
      "effect": "Potent GABA-A receptor agonist producing sedation, dream-like hallucinations, ataxia and altered perception."
    },
    {
      "compound": "Muscazone",
      "amount": "unknown",
      "effect": "Minor photo-degradation product of ibotenic acid with weak psychoactive activity in humans."
    },
    {
      "compound": "Muscarine",
      "amount": "~2–3 mg/kg fresh weight (0.0002–0.0003% of fresh weight)",
      "effect": "Muscarinic cholinergic agonist, but present in amounts far too small to cause sweating, salivation or bradycardia in normal ingestions."
    },
    {
      "compound": "Stizolobic acid",
      "amount": "unknown",
      "effect": "Amino acid precursor of the yellow-orange cap pigments; no established pharmacological effect in humans."
    },
    {
      "compound": "Stizolobinic acid",
      "amount": "unknown",
      "effect": "Pigment-related amino acid with no known significant effect on humans."
    },
    {
      "compound": "Amavadin (vanadium(IV) complex)",
      "amount": "~1000–2000 mg/kg dry weight",
      "effect": "Vanadium-accumulating complex of low acute toxicity; no psychoactive effect, but contributes to the mushroom's heavy-metal load."
    },
    {
      "compound": "Bufotenine (reported traces, disputed)",
      "amount": "unknown",
      "effect": "Serotonergic tryptamine claimed in trace amounts, but its presence is unconfirmed and it contributes no proven effect."
    },
    {
      "compound": "Trehalose",
      "amount": "~5–10% of dry weight",
      "effect": "Storage disaccharide that is digested to glucose; harmless unless the person lacks trehalase."
    },
    {
      "compound": "Mannitol",
      "amount": "~2–5% of dry weight",
      "effect": "Sugar alcohol that can cause mild osmotic bloating or laxative effects in large amounts."
    },
    {
      "compound": "Chitin and beta-glucans (cell wall polysaccharides)",
      "amount": "~10–20% of dry weight",
      "effect": "Largely indigestible fiber that can cause gastrointestinal discomfort and may have mild immunomodulatory activity."
    },
    {
      "compound": "Ergosterol",
      "amount": "~2–5 mg/g dry weight",
      "effect": "Fungal sterol that converts to vitamin D2 under UV light and is otherwise nutritionally inert."
    },
    {
      "compound": "Water",
      "amount": "~88–92% of fresh weight",
      "effect": "Dilutes the active constituents and determines the fresh-to-dry potency ratio."
    }
  ]
}

