    {
      "compound": "Total amatoxins per fruiting body",
      "amount": "5-15 mg per fruiting body",
      "effect": "A single cap can deliver several human lethal doses (about 0.1 mg/kg body weight), causing death without treatment."
    },
    {
      "compound": "Phalloidin (bicyclic heptapeptide phallotoxin)",
      "amount": "0.05-0.2 mg/g",
      "effect": "Stabilizes filamentous actin and destroys liver cell cytoskeleton on injection, but is poorly absorbed from the gut and contributes little to oral poisoning."
    },
    {
      "compound": "Phallacidin",
      "amount": "0.02-0.1 mg/g",
      "effect": "Binds F-actin and is cytotoxic parenterally, with minimal oral toxicity in humans."
