    {
      "compound": "Phalloin, phallisin and phallisacin",
      "amount": "0.01-0.05 mg/g",
      "effect": "Actin-binding phallotoxins that damage hepatocyte membranes experimentally but are weakly active by mouth."
    },
    {
      "compound": "Viroisin / viroidin (virotoxins)",
      "amount": "unknown",
      "effect": "Monocyclic actin-binding peptides with rapid cytotoxic action in laboratory models, negligible oral effect."
    },
    {
      "compound": "Trehalose",
      "amount": "3-8 % of dry weight",
      "effect": "Harmless fungal storage disaccharide digested to glucose by intestinal trehalase."
    },
    {
      "compound": "Mannitol and other polyols",
      "amount": "1-4 % of dry weight",
      "effect": "Nutritive sugar alcohol that can cause mild osmotic laxative effects in large amounts."
    },
    {
      "compound": "Polysaccharides (glycogen, beta-glucans) and chitin",
      "amount": "20-40 % of dry weight",
      "effect": "Largely indigestible or immunomodulatory carbohydrate material with no acute toxicity."
    },
    {
      "compound": "Crude protein and free amino acids (glutamate, aspartate, alanine)",
      "amount": "15-25 % of dry weight",
      "effect": "Provide umami taste and nutrition, which unfortunately makes the mushroom palatable."
    },
    {
      "compound": "Lipids (mainly linoleic acid) and ergosterol",
      "amount": "2-5 % of dry weight",
      "effect": "Ordinary fungal lipids; ergosterol is a provitamin D2 precursor of no toxicological importance here."
    },
    {
      "compound": "Minerals, chiefly potassium and phosphorus",
      "amount": "5-10 % of dry weight",
      "effect": "Normal dietary electrolytes with no toxic contribution to the poisoning."
    }
  ]
}

